<?php
require_once __DIR__ . '/../includes/config.php';
if (!isLoggedIn() || getUserType() !== 'admin') redirectTo('login.php');

$id=(int)($_GET['id']??$_POST['id']??0); $error=''; $success='';
$allowed=['donor','ngo','driver'];
$pdo=getDBConnection();
$user=['id'=>0,'username'=>'','email'=>'','full_name'=>'','organization_name'=>'','phone'=>'','address'=>'','city'=>'','state'=>'','zip_code'=>'','user_type'=>'donor','status'=>'active'];
$driver=['vehicle_type'=>'car','vehicle_number'=>'','license_number'=>''];
if($id){$stmt=$pdo->prepare("SELECT * FROM users WHERE id=? AND user_type IN ('donor','ngo','driver')");$stmt->execute([$id]);$user=$stmt->fetch(PDO::FETCH_ASSOC);if(!$user)die('User not found.'); if($user['user_type']==='driver'){$stmt=$pdo->prepare('SELECT * FROM drivers WHERE user_id=?');$stmt->execute([$id]);$driver=$stmt->fetch(PDO::FETCH_ASSOC)?:$driver;}}
if($_SERVER['REQUEST_METHOD']==='POST'){
    $type=strtolower(trim($_POST['user_type']??'')); $username=strtolower(trim($_POST['username']??'')); $email=strtolower(trim($_POST['email']??'')); $name=trim($_POST['full_name']??''); $password=$_POST['password']??'';
    if(!in_array($type,$allowed,true)||$username===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$name==='')$error='Please provide valid account details.';
    if(!$id && $password==='')$error='Password is required for a new account.';
    if(!$error){try{
        $stmt=$pdo->prepare('SELECT id FROM users WHERE (username=? OR email=?) AND id<>?');$stmt->execute([$username,$email,$id]);if($stmt->fetch())throw new Exception('Username or email already exists.');
        if($id){$sql='UPDATE users SET username=?,email=?,full_name=?,organization_name=?,phone=?,address=?,city=?,state=?,zip_code=?,user_type=?,status=?';$params=[$username,$email,$name,trim($_POST['organization_name']??'' )?:null,trim($_POST['phone']??'')?:null,trim($_POST['address']??'')?:null,trim($_POST['city']??'')?:null,trim($_POST['state']??'')?:null,trim($_POST['zip_code']??'')?:null,$type,($_POST['status']??'active')];if($password!==''){$sql.=',password=?';$params[]=password_hash($password,PASSWORD_DEFAULT);}$sql.=' WHERE id=?';$params[]=$id;$pdo->prepare($sql)->execute($params);}
        else{$status=$type==='ngo'?'pending':'active';$stmt=$pdo->prepare('INSERT INTO users(username,email,password,full_name,organization_name,phone,address,city,state,zip_code,user_type,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$username,$email,password_hash($password,PASSWORD_DEFAULT),$name,trim($_POST['organization_name']??'')?:null,trim($_POST['phone']??'')?:null,trim($_POST['address']??'')?:null,trim($_POST['city']??'')?:null,trim($_POST['state']??'')?:null,trim($_POST['zip_code']??'')?:null,$type,$status]);$id=(int)$pdo->lastInsertId();}
        if($type==='driver'){ $vt=$_POST['vehicle_type']??'car';$vn=trim($_POST['vehicle_number']??'');$ln=trim($_POST['license_number']??'');$stmt=$pdo->prepare('SELECT id FROM drivers WHERE user_id=?');$stmt->execute([$id]);if($stmt->fetch()){$pdo->prepare('UPDATE drivers SET vehicle_type=?,vehicle_number=?,license_number=?,updated_at=NOW() WHERE user_id=?')->execute([$vt,$vn,$ln,$id]);}else{$pdo->prepare('INSERT INTO drivers(user_id,vehicle_type,vehicle_number,license_number,status) VALUES(?,?,?,?,\'available\')')->execute([$id,$vt,$vn,$ln]);}}
        $success='Account saved successfully.';
    }catch(Exception $e){$error=$e->getMessage();}}
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo $id?'Edit':'Add'; ?> User - FoodSave</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/css/style.css" rel="stylesheet"></head><body><div class="container py-5"><div class="card shadow"><div class="card-body p-4"><div class="d-flex justify-content-between"><h2><?php echo $id?'Edit':'Add'; ?> Account</h2><a href="manage_users.php" class="btn btn-secondary">Back</a></div><?php if($error): ?><div class="alert alert-danger"><?php echo htmlspecialchars($error); ?></div><?php endif;?><?php if($success): ?><div class="alert alert-success"><?php echo htmlspecialchars($success); ?> <a href="manage_users.php">Return to users</a></div><?php endif;?><form method="POST" class="row g-3"><input type="hidden" name="id" value="<?php echo (int)$id;?>"><div class="col-md-4"><label class="form-label">Account Type</label><select name="user_type" id="user_type" class="form-select" required><option value="donor" <?php echo $user['user_type']==='donor'?'selected':'';?>>Donor</option><option value="ngo" <?php echo $user['user_type']==='ngo'?'selected':'';?>>NGO / Food Bank</option><option value="driver" <?php echo $user['user_type']==='driver'?'selected':'';?>>Driver</option></select></div><div class="col-md-4"><label class="form-label">Username</label><input class="form-control" name="username" value="<?php echo htmlspecialchars($user['username']);?>" required></div><div class="col-md-4"><label class="form-label">Email</label><input type="email" class="form-control" name="email" value="<?php echo htmlspecialchars($user['email']);?>" required></div><div class="col-md-6"><label class="form-label">Full Name</label><input class="form-control" name="full_name" value="<?php echo htmlspecialchars($user['full_name']);?>" required></div><div class="col-md-6"><label class="form-label">Organization Name</label><input class="form-control" name="organization_name" value="<?php echo htmlspecialchars($user['organization_name']??'');?>"></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?php echo htmlspecialchars($user['phone']??'');?>"></div><div class="col-md-6"><label class="form-label">Password <?php echo $id?'(leave blank to keep current)':'';?></label><input type="password" class="form-control" name="password" <?php echo $id?'':'required';?>></div><div class="col-12"><label class="form-label">Address</label><input class="form-control" name="address" value="<?php echo htmlspecialchars($user['address']??'');?>"></div><div class="col-md-3"><input class="form-control" name="city" placeholder="City" value="<?php echo htmlspecialchars($user['city']??'');?>"></div><div class="col-md-3"><input class="form-control" name="state" placeholder="State" value="<?php echo htmlspecialchars($user['state']??'');?>"></div><div class="col-md-3"><input class="form-control" name="zip_code" placeholder="ZIP" value="<?php echo htmlspecialchars($user['zip_code']??'');?>"></div><div class="col-md-3"><select name="status" class="form-select"><option value="active" <?php echo ($user['status']??'active')==='active'?'selected':'';?>>Active</option><option value="pending" <?php echo ($user['status']??'')==='pending'?'selected':'';?>>Pending</option><option value="inactive" <?php echo ($user['status']??'')==='inactive'?'selected':'';?>>Inactive</option></select></div><div id="driverFields" class="row g-3 <?php echo $user['user_type']==='driver'?'':'d-none';?>"><div class="col-md-4"><label class="form-label">Vehicle Type</label><select name="vehicle_type" class="form-select"><option value="car">Car</option><option value="van">Van</option><option value="truck">Truck</option><option value="bicycle">Bicycle</option><option value="motorcycle">Motorcycle</option></select></div><div class="col-md-4"><label class="form-label">Vehicle Number</label><input class="form-control" name="vehicle_number" value="<?php echo htmlspecialchars($driver['vehicle_number']??'');?>"></div><div class="col-md-4"><label class="form-label">License Number</label><input class="form-control" name="license_number" value="<?php echo htmlspecialchars($driver['license_number']??'');?>"></div></div><div class="col-12"><button class="btn btn-success" type="submit">Save Account</button></div></form></div></div></div><script>const t=document.getElementById('user_type'),d=document.getElementById('driverFields');t.addEventListener('change',()=>d.classList.toggle('d-none',t.value!=='driver'));</script></body></html>
